1	# Mermaid.js Integration Patterns
2	
3	JavaScript API integration, HTML embedding, and platform-specific usage.
4	
5	## HTML/Browser Integration
6	
7	**Basic CDN Setup:**
8	```html
9	<!DOCTYPE html>
10	<html>
11	<head>
12	  <script src="https://cdn.jsdelivr.net/npm/mermaid@latest/dist/mermaid.min.js"></script>
13	</head>
14	<body>
15	  <pre class="mermaid">
16	    flowchart TD
17	      A[Client] --> B[Load Balancer]
18	      B --> C[Server 1]
19	      B --> D[Server 2]
20	  </pre>
21	  <script>
22	    mermaid.initialize({ startOnLoad: true });
23	  </script>
24	</body>
25	</html>
26	```
27	
28	**ES Module (Modern):**
29	```html
30	<script type="module">
31	  import mermaid from 'https://cdn.jsdelivr.net/npm/mermaid@latest/dist/mermaid.esm.min.mjs';
32	  mermaid.initialize({ startOnLoad: true });
33	</script>
34	```
35	
36	## NPM/Node.js Integration
37	
38	**Installation:**
39	```bash
40	npm install mermaid
41	# or
42	yarn add mermaid
43	```
44	
45	**Import and Initialize:**
46	```javascript
47	import mermaid from 'mermaid';
48	
49	mermaid.initialize({
50	  startOnLoad: true,
51	  theme: 'dark',
52	  securityLevel: 'strict'
53	});
54	```
55	
56	**Manual Rendering:**
57	```javascript
58	import mermaid from 'mermaid';
59	
60	const graphDefinition = `
61	  graph TD
62	    A[Start] --> B[Process]
63	    B --> C[End]
64	`;
65	
66	const { svg } = await mermaid.render('graphId', graphDefinition);
67	document.getElementById('container').innerHTML = svg;
68	```
69	
70	## React Integration
71	
72	**Component Wrapper:**
73	```jsx
74	import { useEffect, useRef } from 'react';
75	import mermaid from 'mermaid';
76	
77	function MermaidDiagram({ chart }) {
78	  const ref = useRef(null);
79	
80	  useEffect(() => {
81	    mermaid.initialize({ startOnLoad: false });
82	    if (ref.current) {
83	      mermaid.render('diagram', chart).then(({ svg }) => {
84	        ref.current.innerHTML = svg;
85	      });
86	    }
87	  }, [chart]);
88	
89	  return <div ref={ref} />;
90	}
91	
92	// Usage
93	<MermaidDiagram chart="graph TD
A-->B" />
94	```
95	
96	**Next.js (App Router):**
97	```jsx
98	'use client';
99	import dynamic from 'next/dynamic';
100	
101	const Mermaid = dynamic(() => import('./MermaidDiagram'), {
102	  ssr: false
103	});
104	
105	export default function Page() {
106	  return <Mermaid chart="flowchart TD
A-->B" />;
107	}
108	```
109	
110	## Vue Integration
111	
112	**Component:**
113	```vue
114	<template>
115	  <div ref="container"></div>
116	</template>
117	
118	<script setup>
119	import { ref, onMounted, watch } from 'vue';
120	import mermaid from 'mermaid';
121	
122	const props = defineProps(['chart']);
123	const container = ref(null);
124	
125	onMounted(() => {
126	  mermaid.initialize({ startOnLoad: false });
127	  renderDiagram();
128	});
129	
130	watch(() => props.chart, renderDiagram);
131	
132	async function renderDiagram() {
133	  const { svg } = await mermaid.render('diagram', props.chart);
134	  container.value.innerHTML = svg;
135	}
136	</script>
137	```
138	
139	## Markdown Integration
140	
141	**GitHub/GitLab:**
142	````markdown
143	```mermaid
144	graph TD
145	  A[Start] --> B[End]
146	```
147	````
148	
149	**MDX (Next.js/Gatsby):**
150	```mdx
151	import Mermaid from './Mermaid';
152	
153	# Architecture
154	
155	<Mermaid chart={`
156	  flowchart LR
157	    Client --> API
158	    API --> Database
159	`} />
160	```
161	
162	## API Reference
163	
164	**mermaid.initialize(config)**
165	Configure global settings.
166	```javascript
167	mermaid.initialize({
168	  startOnLoad: true,
169	  theme: 'dark',
170	  logLevel: 3,
171	  securityLevel: 'strict',
172	  fontFamily: 'Arial'
173	});
174	```
175	
176	**mermaid.render(id, graphDefinition, config)**
177	Programmatically render diagram.
178	```javascript
179	const { svg, bindFunctions } = await mermaid.render(
180	  'uniqueId',
181	  'graph TD
A-->B',
182	  { theme: 'forest' }
183	);
184	```
185	
186	**mermaid.parse(text)**
187	Validate syntax without rendering.
188	```javascript
189	try {
190	  await mermaid.parse('graph TD
A-->B');
191	  console.log('Valid');
192	} catch(e) {
193	  console.error('Invalid:', e);
194	}
195	```
196	
197	**mermaid.run(config)**
198	Render all diagrams in page.
199	```javascript
200	await mermaid.run({
201	  querySelector: '.mermaid',
202	  suppressErrors: false
203	});
204	```
205	
206	## Event Handling
207	
208	**Click Events:**
209	```javascript
210	const graphDefinition = `
211	  flowchart TD
212	    A[Click me] --> B
213	    click A callback "Tooltip text"
214	`;
215	
216	window.callback = function() {
217	  alert('Node clicked!');
218	};
219	
220	await mermaid.render('graph', graphDefinition);
221	```
222	
223	**Interactive URLs:**
224	```
225	flowchart TD
226	  A[GitHub] --> B[Docs]
227	  click A "https://github.com"
228	  click B "https://mermaid.js.org" "Open docs"
229	```
230	
231	## Advanced Patterns
232	
233	**Dynamic Theme Switching:**
234	```javascript
235	function updateTheme(isDark) {
236	  mermaid.initialize({
237	    theme: isDark ? 'dark' : 'default',
238	    startOnLoad: false
239	  });
240	
241	  // Re-render all diagrams
242	  document.querySelectorAll('.mermaid').forEach(async (el) => {
243	    const code = el.textContent;
244	    const { svg } = await mermaid.render('id', code);
245	    el.innerHTML = svg;
246	  });
247	}
248	```
249	
250	**Lazy Loading:**
251	```javascript
252	const observer = new IntersectionObserver((entries) => {
253	  entries.forEach(async (entry) => {
254	    if (entry.isIntersecting) {
255	      const code = entry.target.textContent;
256	      const { svg } = await mermaid.render('id', code);
257	      entry.target.innerHTML = svg;
258	      observer.unobserve(entry.target);
259	    }
260	  });
261	});
262	
263	document.querySelectorAll('.mermaid').forEach(el => observer.observe(el));
264	```
265	
266	**Server-Side Rendering (SSR):**
267	```javascript
268	import { chromium } from 'playwright';
269	
270	async function renderServerSide(code) {
271	  const browser = await chromium.launch();
272	  const page = await browser.newPage();
273	
274	  await page.setContent(`
275	    <script src="mermaid.min.js"></script>
276	    <div class="mermaid">${code}</div>
277	    <script>mermaid.initialize({ startOnLoad: true });</script>
278	  `);
279	
280	  const svg = await page.locator('.mermaid svg').innerHTML();
281	  await browser.close();
282	  return svg;
283	}
284	```
285	
286	## Platform-Specific
287	
288	**Jupyter/Python:**
289	Use mermaid.ink API:
290	```python
291	from IPython.display import Image
292	diagram = "graph TD
A-->B"
293	url = f"https://mermaid.ink/svg/{diagram}"
294	Image(url=url)
295	```
296	
297	**VS Code:**
298	Install "Markdown Preview Mermaid Support" extension.
299	
300	**Obsidian:**
301	Native support in code blocks:
302	````markdown
303	```mermaid
304	graph TD
305	  A --> B
306	```
307	````
308	
309	**PowerPoint/Word:**
310	Use mermaid.live editor → Export → Insert image.
