import puppeteer from 'puppeteer';
import fs from 'fs';

const htmlContent = `
<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.jsdelivr.net/npm/mermaid@latest/dist/mermaid.min.js"></script>
</head>
<body>
  <pre class="mermaid">
radar-beta
  axis Order Price | Fuel Eff | Power | Safety | Interior | Resale | Emissions
  SUV: [55.6, 46.9, 68, 81.1, 78.2, 74.1, 42]
  Sedan: [68.6, 66.25, 57.5, 84, 53.6, 65.6, 58.25]
  Electric: [52, 86.75, 73, 83.6, 63.6, 54.8, 98]
  bounds: 0 --> 100
  </pre>
  <script>
    mermaid.initialize({ startOnLoad: true, theme: 'neutral' });
  </script>
</body>
</html>
`;

fs.writeFileSync('/app/output/temp.html', htmlContent);

const browser = await puppeteer.launch({
  headless: true,
  args: ['--no-sandbox', '--disable-setuid-sandbox']
});

const page = await browser.newPage();
await page.setViewport({ width: 1200, height: 800 });
await page.goto('file:///app/output/temp.html', { waitUntil: 'networkidle0' });

// Wait for mermaid to render
await page.waitForSelector('.mermaid svg', { timeout: 10000 });

const svg = await page.$eval('.mermaid svg', el => el.outerHTML);
fs.writeFileSync('/app/output/result.svg', svg);

await browser.close();
console.log('SVG saved to /app/output/result.svg');

