import sharp from 'sharp';
import fs from 'fs';

const svgContent = fs.readFileSync('/app/output/result.svg', 'utf8');

sharp(Buffer.from(svgContent))
  .png()
  .toFile('/app/output/result.png')
  .then(() => {
    console.log('PNG saved to /app/output/result.png');
  })
  .catch(err => {
    console.error('Error:', err);
  });

